const INDEX = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Olympus Verify</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<link rel=\"stylesheet\" href=\"/static/policies.css\">\n</head>\n<body class=\"olympus-policy\">\n<a class=\"skip-link\" href=\"#policy-content\">Skip to policy</a>\n<header class=\"policy-header\">\n<a class=\"brand\" href=\"/\"><img src=\"/static/olympus-icon.png\" alt=\"\" width=\"40\" height=\"40\">Olympus</a>\n<nav aria-label=\"Policies\"><a href=\"/privacy\">Privacy Policy</a><a href=\"/terms\">Terms of Service</a></nav>\n</header>\n<main id=\"policy-content\" tabindex=\"-1\">\n<h1>Olympus Verify</h1>\n<p>A private Discord bot for one World of Warcraft guild, and the guild's registration site. It confirms that a Discord\naccount and an in-game character belong to the same person, so guild channels can be opened without an officer checking\nevery name by hand. It serves the Olympus channels in Asmongold's Discord server, and it is not offered to the\npublic.</p>\n<ul>\n  <li><a href=\"/privacy\">Privacy Policy</a></li>\n  <li><a href=\"/terms\">Terms of Service</a></li>\n</ul>\n<!-- olympus:slot ACCOUNT_CONTROLS start -->\n<section class=\"data-controls\"><h2>Privacy and account data</h2><p><a href=\"https://olympus.roachcouncil.com/privacy/account\">Account data controls</a> · <a href=\"https://olympus.roachcouncil.com/privacy/access\">Connect Discord for privacy actions</a> · <a href=\"https://olympus.roachcouncil.com/privacy/case\">Read an existing case</a></p></section>\n<!-- olympus:slot ACCOUNT_CONTROLS end -->\n<!-- olympus:slot BNET_LOGIN start -->\n\n<!-- olympus:slot BNET_LOGIN end -->\n</main>\n</body>\n</html>\n";
const PRIVACY = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Olympus Verify — Privacy Policy</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<link rel=\"stylesheet\" href=\"/static/policies.css\">\n</head>\n<body class=\"olympus-policy\">\n<a class=\"skip-link\" href=\"#policy-content\">Skip to policy</a>\n<header class=\"policy-header\">\n<a class=\"brand\" href=\"/\"><img src=\"/static/olympus-icon.png\" alt=\"\" width=\"40\" height=\"40\">Olympus</a>\n<nav aria-label=\"Policies\"><a href=\"/privacy\" aria-current=\"page\">Privacy Policy</a><a href=\"/terms\">Terms of Service</a></nav>\n</header>\n<main id=\"policy-content\" tabindex=\"-1\">\n<h1>Privacy Policy</h1>\n<p class=\"meta\">Olympus Verify and the Olympus guild site · last updated 10 October 2026</p>\n\n<p>Olympus Verify is a private bot run by the volunteer staff of the World of Warcraft guild &ldquo;Olympus&rdquo;. It\nserves the Olympus channels in Asmongold's Discord server, and it is not offered to the public or installed anywhere\nelse. It exists to prove that a Discord account and an in-game character belong to the\nsame person, so guild channels can be opened to guild members without an officer checking every name by hand.</p>\n\n<h2>Privacy contact</h2>\n<p>Olympus volunteer administration handles privacy questions and requests. Use the\n<a href=\"https://olympus.roachcouncil.com/privacy/access\">privacy account connection</a> for your own retained-data download or serving-account erasure. Existing case IDs and private codes still open their conversations. An Olympus officer arranges attended handling for unresolved records or permissions. Do not put passwords, authentication tokens or identity documents in guild messages.</p>\n\n<h2>Age and eligibility</h2>\n<p>You must be at least 13 and meet any higher minimum age required by Discord or the law where you live. You must\nalso be eligible to use World of Warcraft under the Blizzard terms that apply to your region. Obtain any agreement\nfrom a parent or legal guardian required by those terms. Discord sign-in does not verify your age for Olympus.</p>\n\n<h2>What it stores</h2>\n<p>Only what that check needs: your Discord user ID and display name; the characters you verify, with where each stands (code confirmed, invite queued, sent or refused,\njoined or left) and when; the in-game guild roster as the officers' addon exports it &mdash; each member's character name,\nrank, level, class, public and officer notes and last-online time, and the date the name first appeared &mdash; kept as\ndated snapshots (where the officers have switched on the guild note, the public note the bot has the addon write when you\njoin is <code>D:</code> followed by your Discord user ID, and every later export carries it), each also recording when that\nexact roster first arrived, whether all of it was stored, and whether it passed the bot's size checks (not much smaller\nthan the last export that passed them and not below a set minimum, or an officer vouched for it); a rank is the one the\nguild gives in game and can reflect a staff decision (for example a probation rank, where the guild uses one), and the\nsnapshots keep it as it was exported; and a dated log of actions\ntaken (role granted, role removed, application approved or denied, a character unbound, a ban), each entry naming who\nacted, whom or what it concerned and the fixed details that action records (a denial or ban reason as the officer typed\nit; for an unbind, the account the character was bound to before), so officers can answer &ldquo;why did this\nhappen&rdquo;. It also keeps your Discord username and display name, as Discord reports them, for the characters you have\nlinked.</p>\n\n<h2>The guild site</h2>\n<p>The Olympus registration site (olympus.roachcouncil.com; its old address, guild.roachcouncil.com, forwards to it)\nsigns you in with Discord and checks one thing about your\nservers: whether you are a member of Asmongold's Discord server. For that it asks Discord for your identity and your\nmembership in that one server. It stores your Discord user ID, username, display name, nickname and avatar in that\nserver, when your Discord account was created and when you joined that server; what you enter &mdash; your application\n(your first choice and up to two backup roles, your answers, and the professions you plan to take if you name any),\nthe times of the week you usually play (kept as hours of the week in UTC, with your time zone), your votes on the\nvoting board, the people you write in for a role and why, the friends you list, and the character names you reserved\n&mdash; and when you signed in. Discord sign-in requests your identity and membership in this server; it does not\nrequest your Discord email address, password, other-server list or messages. Personal information you type into\nforms can be stored as part of those entries. The site keeps no Discord access token after sign-in. The site's top bar shows you your own\nDiscord picture: your browser loads it from Discord's picture server (cdn.discordapp.com), so Discord sees that request;\nthe site shows that picture to no one else.</p>\n<p><strong>The voting board.</strong> Leadership roles are voted on, except those the guild's leadership chooses\nwithout a public vote (the site marks them); an application for only such roles is not shown on the board. If you\napply for a role that is voted on and tick the box that shows your application on the voting board, every member\nsigned in to the site can read it there, under each role you chose that is voted on then or later: your Discord display\nname and, as its picture, the game's own class icon for the class you gave (the board shows the game's icons, never your\nDiscord picture; the avatar reference Discord gave at sign-in stays stored with your account record, as said above),\nyour class, role and where you play from, which roles you chose (first choice or backup), how many NA and\nEU raid evenings a week you can make, and your answers to the four questions about your experience, why Olympus,\nleading people, and the loot argument. Your main character, professions, logs, references, voice chat, hours, weekly\nschedule and the last free-text box are never shown there. An application leaves the board when you withdraw it or\nonce the leadership has decided it. Votes on the board and people written in for a role are counted and seen only by\nthe site's administrators; nobody else, including the applicants and the people written in, sees how anyone voted or\nany counts. Someone you write in is told the role the next time they sign in, never by whom.</p>\n<p><strong>Appointed roles.</strong> The site's administrators may fill a role by appointment instead of the board and\ntype the holder's name (up to 40 characters, tied to no Discord account), and they type a name only after that person\nagreed. An appointed name is public: anyone, signed in or not, sees it on the Roles page and wherever the site names the\nrole, the site's public settings carry it, and search engines and web archives on the open web may copy it; removing it\nhere cannot recall their copies. An appointment gives no powers in the bot, the site or Discord, and an administrator\nclears it after the beta has closed. The dated log records which roles were appointed and how many names were saved,\nnever the names (and whether the site-wide notice was set, never its text). Build .115 rewrites the entries written\nbefore it the same way, once, when it first starts; if that fails, the failure is logged and the rewrite is tried again\nat a later start, and after installing it the owner checks that the rewrite is recorded as done and that no such entry\nstill holds a name or a notice's text.</p>\n<p>Voting-board sharing and directory listing are separate choices. For names entered by staff, staff must obtain the\nperson's agreement before publication; the server records the staff confirmation, not the person's agreement itself.\nDiscord sign-in is permission to identify your Discord account and check this server membership. It does not verify\nyour age or automatically authorize every separate publication of your information.</p>\n<p><strong>A full guild.</strong> While Olympus I is full (the officers' latest roster export counts the member limit,\nwhen that export is complete, passed the size checks and is less than two days old; or an invite was just refused for\nlack of space), <code>/verify-status</code> says so, with the hour of that export or refusal, to an account waiting on an\ninvite, and the site's Home and Apply pages say so to an account waiting in the invite queue (with its place) or without\na confirmed character (with that hour). Your own characters' places in the invite queue are shown to you, and only you.\nNo other member sees your place. Officers see the invite queue itself (the character names, the accounts and their\norder) in their staff commands, and the bot's private staff channels record each confirmation (the character and the\naccount, never a code) and, while the guild is full, how many are waiting.</p>\n\n<h2>The community pages</h2>\n<p>The site has community pages that the guild's staff switch on one at a time; a page that is off shows nothing and\ntakes no new entries or actions, while what it already holds stays in your copy, keeps the lifetime stated below, is\ncleaned up on the same schedule, can still be erased on request, and stays in the dated log as before. Each stores only\nwhat you enter there or\nwhat the officers record, under your Discord user ID. Nothing on these pages changes your Discord roles, your guild\nmembership or your access by itself: the officers decide those, and this software keeps the records.</p>\n<p><strong>Member directory and crafting offers.</strong> You may list, for other guild members, a main character, a\nraid role, up to four professions with a skill level, up to ten alts you claim, and up to fifty crafting offers. They are\nshown to members signed in to the site whose own character the officers' roster export confirms, only while you keep them\nlisted and remain such a member yourself; other members see you by your display name and a random reference, never your\nDiscord user ID. A character name you enter is a label until it matches the officers' record of your characters; a name\nbound to another account is refused. Officers may confirm or reject a claimed alt. A profile whose owner is no longer a\nconfirmed member stops being shown at once and is deleted, with everything under it, by the scheduled cleanup from\nthirty days later.</p>\n<p><strong>The leadership directory.</strong> The site's administrators may list, for each Olympus guild (Olympus I to\nOlympus X), its Guild Master and officers by the names they type, and they list a name only after that person agreed.\nConfirmed members can read it. A listing is a record only: it gives no powers in the bot, the site or Discord. An\nadministrator clears it after the beta has closed and changes it when the leadership changes. Anyone listed there or\nappointed to a role (see the guild site, above) can ask any Olympus officer, or use the privacy account help page, to have\nthe name removed or corrected, and an administrator does it at once: the name is cleared, or replaced by &ldquo;Name\nwithheld&rdquo;, which keeps an appointed role appointed.</p>\n<p><strong>News.</strong> When the site's administrators switch it on (it is off until they do), confirmed members can\nread a News page. It shows notices the administrators post for the whole guild, and figures the site works out by\nitself: whether Olympus I has room, with the hour of the roster export or refused invite that says so; how many characters\njoined and left the guild in the last day and the last seven days, compared between complete roster exports that passed\nthe size checks; how many applications were first saved and how many decisions were saved in the same periods, where a\ncount from one to four is shown only as &ldquo;fewer than 5&rdquo;; when the leadership directory last changed, never its\nnames; the beta's dates; and the site's release notes. The figures are counts and times, never a name or anyone's place\nin line, and are worked out at most every three hours, only while the page is on. The page also lists the next events\nby their start times and the titles their organizers gave them; a title is free text, shown exactly as the calendar\nalready shows it to confirmed members (see Calendar and attendance). A notice is different: it is free text an\nadministrator writes for the whole guild, shown as plain text,\nand the site does not check what it says. The administrators name a member in a notice only with that member's\nagreement, and anyone a notice names can ask any Olympus officer, or use the privacy account help page, to have it changed or\ndeleted, and an administrator does it at once. A notice is shown for the period the administrator chose, from 1 to 90\ndays after it was first posted (judged by the database's own clock in every read), and then deleted by the scheduled\ncleanup; an administrator may change or delete it sooner. Members see when a notice was posted and last changed, not who\nwrote it: the administrator who posted it and the one who last changed it are recorded for the staff only. A notice that\nwas deleted or ran out leaves behind only its id, who posted it and when, until 120 days after it was posted, and a page\ncan post a new notice only within 30 days of being opened, so a page opened earlier cannot post it again. The dated log\nrecords that a notice was posted, changed or deleted and how many are shown, never a title or a text.</p>\n<p><strong>Calendar and attendance.</strong> Organizers (the site's administrators and the members named as organizers)\ncreate events: a title, details, start, duration, capacity and the roles wanted. You answer yes, tentative or no with a\ncharacter and a raid role, and you can give or change that answer only before the event starts, while the calendar is on\nand you are a confirmed member; your answer, display name and character are visible to confirmed members looking at the\nevent, and it holds a place only while you remain one. After an event started an organizer may record\nattendance (present, possibly late or having left early; absent; excused; or unknown). Attendance never feeds roles,\neligibility or any penalty. An event, its answers, attendance and history are deleted by the scheduled cleanup from\nthirty days after it ends (a cancellation brings that forward).</p>\n<p><strong>Trial reviews.</strong> Officers may record a trial about your account: when it began, when its review is\ndue, whether it was extended, and how it concluded (passed, or ended with a fixed reason). You can read your own trial's\nstatus and dates on the site, never the sponsor or the officers involved. A trial is kept thirty days after it concluded,\nor after its review was due if it never did; from that moment no page shows it and no new copy contains it, and the row\nis deleted in the scheduled cleanup (bounded batches, so it may take more than one run).</p>\n<p><strong>Restriction cases, the watch-list and the return review.</strong> Officers may record a case about a Discord\naccount &mdash; a ban, a removal for conduct, or a removal for unpaid guild dues &mdash; with its dates, review and appeal\ndecisions, and may record that the same account signed in again after the case was set. A case may carry a watch-list:\nthe names and in-game identifiers of that account's characters, copied from the officers' own record, so the officers can\nsee when another account later holds one of them. Watch-list rows are kept for at most twelve months per member (one\nperiod, which an officer may renew with a fixed reason), never longer than their case. These are staff records and review\nevidence only: nothing here bans, removes or recognizes anyone by itself. A removal case ends at its expiry (at most two\nyears), a ban case when an officer resolves it; a resolved case is kept thirty days. Past those moments no page shows the\ncase and no new copy contains it.</p>\n<p><strong>Departure review items.</strong> When a character bound to your account leaves or is removed from the\nin-game guild, a review item (the character, whether it left or was removed, the date) exists for thirty days so an\nofficer can acknowledge it or open a case from it. Nothing is decided by the item itself.</p>\n<p><strong>Guild dues (the contribution ledger).</strong> When the officers switch it on, the site keeps a ledger of the\nweekly guild dues in in-game copper: your weeks (eligible or exempt, due, paid, acknowledged), the payments the officers\nrecord (amount, date and source; the payer name as written in the game is for officers only), and your acknowledgements\nof a notice. The site shows you a mail reference to put in the subject of the in-game mail so an officer can match it to\nyou; it is a matching aid, not proof of payment &mdash; the officer records the payment. Nothing is sent to you or taken\nfrom you by this software; an officer may record that you were removed in game for unpaid dues, which is a record, not an\naction. Ledger records are kept for the period the officers set when they switch it on (between one day and ten years,\nfixed when each record is written). Past its period a week is answered to no one; past its period a recorded payment's\nprivate details (its source identifier, the payer name as written, who recorded it) become unavailable at once and its\nunused remainder can never pay a later week, with one narrow exception kept on purpose: while a payment already paid a\nweek that is itself still within its period, the minimum the accounting needs stays with that week: the payment's kind\n(an officer's entry, a mail, a bank log), the amount it paid that week and the part already retired, its date and status,\nand which week it paid; nothing more, so the week's paid state is never falsified, and it goes when the week goes.</p>\n\n<p>Discord and Blizzard authenticate their own accounts; Olympus does not ask for those account passwords. Discord\nsign-in does not request your email address or your Discord messages. Free-text fields, including applications,\nprivacy inbox conversations and staff notes, store the text supplied and may contain email addresses or other personal\ninformation. Include only what is needed; do not send passwords, tokens or identity documents. A connection IP address\nis used for short-lived rate limiting; it is not written into the privacy inbox case record. This describes the\napplication code, not a promise about all network data processed by its hosting provider. Olympus does not process\nreal-money payments. The in-game copper the guild dues ledger records is described under the community pages. In the game, the officers' addon reads the\nverification codes whispered or mailed to an officer's character, the game's own guild join and leave messages, the guild\nroster and the result of each invite it sends. A companion program on that officer's computer reads the game client's chat\nlog file (which holds whatever chat that client logs) and the addon's saved data, and forwards to the bot only what it\nextracts from them: the code, the character and guild names, the invite outcomes, the roster export, whether that officer\nis in the world, and a timing measurement of the log file itself. By its code nothing else is sent, and the chat log stays\non that officer's computer; this describes the software as written, not a guarantee about the game client.</p>\n\n<p><strong>If you are banned from verifying</strong>, the bot keeps your Discord user ID and the reason; the\ncharacters bound to that account stay bound to it.</p>\n<p><strong>Battle.net.</strong> Battle.net sign-in is currently switched off. No active Battle.net login data\ncollection or Forever ownership check is provided. Any records left by an earlier link are legacy records, not proof\nof Forever character ownership; ask Olympus volunteer administration about those Olympus records. Discord separately\nkeeps its linked-role connection under your Discord account. You can remove that connection in Discord's Settings\nunder Connections. No future Battle.net login retention period is promised while the feature is disabled.</p>\n<p><strong>Renames Blizzard required.</strong> When a roster export shows that a character bound to you was renamed (the\nsame character under a new name), the link follows the character and the site's administrators see the old and new\nname. If an administrator marks the rename as required by Blizzard, the bot records that decision (your Discord user\nID, both names, that character's key and in-game identifier, when it was decided, by whom, and when it was closed): the\ncharacter is unbound and has to be verified again, your site application is set back so that you submit it again, your\nGuild Member role is removed and held unless another of your characters is in the guild, and <code>/verify-status</code>\ntells you why; an administrator approves once your new application was accepted and the character verified again, or\nwithdraws the decision. The record is deleted thirty days after it was approved or withdrawn; while it is open it\nstays.</p>\n\n<h2>Where it goes</h2>\n<p>Data lives in a Cloudflare D1 database owned by the guild's officers, in Cloudflare's infrastructure, together with\nthe site's files and the Worker's operational logs. The reviewed error logger reduces error details to categories and\nbounded status codes. Some error paths also log truncated request paths or command and component labels, which can\ninclude user-supplied text. Cloudflare's operational logging and retention settings apply to that output. A working copy\nof the invite queue, the addon's saved data and\nthe game's chat log sit on the computer of the officer who sends the invites. The bot talks to Discord as part of its\nordinary work: it reads members' roles and nicknames, grants and removes the Guild Member role, sets nicknames where that\nis switched on, bans where an officer orders it, writes a short reason into Discord's own audit log for those changes,\nrefreshes the Discord usernames and display names of linked members, re-checks a signed-in member's server membership\nabout hourly after a save, and posts the notices and staff messages described below; Discord keeps its own records of all\nthat under its terms. While Battle.net sign-in is switched off, Blizzard receives nothing from this bot. Nothing is sold or used for\nadvertising, training or analytics, and there are no third-party trackers on this page; beyond what this page describes,\nnothing is shared.</p>\n\n<h2>Who can see it</h2>\n<p>Guild officers, through the bot's own commands and their in-game addon, can see which Discord account a character\nbelongs to, its Discord username and display name, and how its verification went. The same lookup tells them whether\nyou applied on the guild site, for which role and how far it got, and the character names you reserved. The site's\nadministrators can see everything you entered on the site. Other members can see that you have signed up there (when\nthey search for someone to write in or list as a friend), if you put a leadership application on the voting board, what\nthe board shows, and what you list for them on the community pages (your directory profile and crafting offers, your\ncalendar answers), as those sections say; nothing else you entered. Confirmed members can also read the News page while\nit is on: the figures the site works out by itself, which are counts and times and never your name or your place in the\ninvite queue; the next events with the titles their organizers gave them, as the calendar shows them; and the notices\nthe administrators write for the whole guild, which name a member only with that member's agreement (see News, above,\nto have one changed or deleted). If you hold an appointed role, anyone, signed in or not,\nsees your name as its holder, as said under the guild site. Beyond that, everyone else in the server sees only what the\nbot shows in public: your server nickname, where the staff\nhave switched that on, which it then sets to your character's name when you are admitted; and the short notices in the server's bot notices channel (#olympus-notices) that mention you\nwhen your access changes. The Terms of\nService list which notices those are; anything you might not want read out only says there is an update, and\n<code>/verify-status</code> shows the detail to you alone. The bot's log channel is private to staff.</p>\n<p>The site's administrators also use the staff pages of the community features: the directory's claims review,\ntrials, cases and their watch-lists, departure items, the dues ledger with the payer names and sources of recorded\npayments, the privacy inbox cases, the News notices with who posted and last changed each, and two staff views that\nchange nothing: a coverage report (the latest roster export\nnext to what the bot and the site already know about each bound account) and the counts behind the officer digest. Every\nchange a staff member makes is recorded in the dated log under their Discord user ID; reading is not. Once a day the bot\nmay post to a staff channel how many things wait for an officer, as counts only, never a name or an ID. A staff\nrank-planning page keeps its draft in that administrator's own browser and stores nothing on the server; that browser\ncopy outlives signing out and any deletion on the server until the administrator clears their browser's data.</p>\n\n<h2>Councillor browser verification</h2>\n<p>AddOn-free members send their website verification code as an ordinary in-game whisper to an online qualified High Councillor. The councillor runs the AddOn and browser scanner; the browser holds a non-extractable signing key locally and the service stores its public key with a fixed twenty-four-hour lease. A separately accepted automatic scanner session lasts at most five minutes and ten proofs. Signing needs that councillor's game and browser to be running; Cloudflare alone cannot observe game membership. Proofs are councillor attestations, not Blizzard-issued ownership certificates.</p>\n<p>The service keeps the request, challenge, account and generation, character GUID and name, native rank, roster reference, proof digest and signed role-settlement outcome. Current server checks, the configured native-rank profile, fresh complete roster evidence and one-use proof authority govern bot effects. Lost effects are reconciled without blindly repeating them. Browser keys remain in the councillor's browser until revoked or its local storage is cleared; server-side account erasure cannot reach that local copy. Account downloads omit public-key material, authentication secrets, proof digests and counterpart identities.</p>\n\n<h2>Getting rid of it</h2>\n<p>Open <a href=\"https://olympus.roachcouncil.com/privacy/account\">Account data controls</a> for your current site session, or <a href=\"https://olympus.roachcouncil.com/privacy/access\">connect Discord for privacy actions</a>. The separate connection asks Discord only to identify your account. It does not require server membership or create a guild-site account, and grants no guild, staff or bot role access. It lasts twelve minutes, with a separate one-use form for a curated copy and for serving-account erasure. Its authentication handshake expires after five minutes. Short-lived authentication hashes and form credentials are not included in downloads.</p>\n<p>Explicitly requesting erasure closes the current account generation to ordinary site saves and new bot-managed role grants. A bounded scheduled job first confirms that your bot-managed Olympus Guild Member role is absent or removes it through the central role writer. If Discord is unavailable, the role outcome is unknown, an old operation is unresolved, or an unclassified store or ambiguous reference is present, completion is held. Manually assigned staff permissions need human handling. Keep the request ID and private status code: they read only that request until its original deadline and never restore ordinary account access. A lost response does not prove rollback or completion.</p>\n<p>Qualified serving-account erasure removes the account and application, linked characters and their identifiers, requests and queue entries, attributable roster rows and notes, first-seen rows, inactive relay references, votes and friends, reserved names, registered community records, verification keys and proofs, settled role records, attributable operational actions, and the short-lived privacy connection. It scrubs covered staff-actor pointers and structured references. Typed appointments, directory names and arbitrary text are not assumed to identify your account; ambiguous references can hold completion and need attended correction. An independent later game census can contain current game facts again, without restoring your erased account link. Unbinding alone and leaving Discord are not erasure.</p>\n<p><strong>Separate safety purposes.</strong> An active verification ban and its necessary reason, unresolved safety cases and their watch records can remain under their separate rules. For your own rejected guild application or membership, erasure retains a keyed, minimized account marker with the fixed reason and original decision date for up to 365 days from that decision. It does not retain your application, name or rejection explanation, does not mean a general ban, and retries do not extend its deadline. A separate restore-suppression record holds the retired Discord account identifier and generation for 366 days from erasure, to prevent an old recovery copy from reviving that generation.</p>\n<p><strong>Discord messages.</strong> The service tracks bounded bot-created review, notice, guild-log, event-publication and reminder pointers it can attribute. It requests cleanup and confirms absence; a lost send or deletion response is kept as unresolved custody without automatic resend. Known pointers can continue cleanup after local account erasure. Unknown outcomes or unresolved records beyond their original deadline need attended resolution and are not silently called erased. Other people's messages and copies remain with their holders. The status explicitly separates serving-account completion, Discord cleanup and recovery copies.</p>\n<p><strong>Automatic retention.</strong> Inactive site accounts with no active linked character and dated inactive bot accounts become eligible for serving erasure after twelve months. Unsuccessful applications, ended links, unused requests, released reserved names, departed-account references, inactive relays and expired operational history use bounded cleanup with their original clocks. Undated legacy evidence is held for review. Beta requests and first-seen dates age from the eventual beta cutoff only after the attended reset confirms that cutoff; the original dates are preserved. An event cannot be scheduled more than 366 days beyond its original creation to perpetuate its records. Existing shorter trial, case, dues and News lifetimes continue to apply.</p>\n<p>Where a record has a stated read cutoff, the database clock controls availability. Physical deletion follows in bounded scheduled batches and can need several runs or wait for a schema or provider hold. Profiles become unavailable when their owner no longer qualifies and are cleaned thirty days later. Events, answers and attendance are cleaned thirty days after the event ends. Unresolved safety cases, provider outcomes and active bans have separate purposes. Cleanup does not recall a downloaded, browser, game-client, officer-computer or provider copy.</p>\n<p><strong>Existing private cases.</strong> New privacy-inbox requests are replaced by the account controls above. Existing conversations can still be read with their case ID and private code at <a href=\"https://olympus.roachcouncil.com/privacy/case\">Read an existing case</a>. The code controls that conversation only, not an account. Cases keep their fixed-at-creation inactivity policy; messages or staff changes can extend an open case, reads do not, and closing fixes its deadline. Scheduled cleanup removes expired cases. Ask an Olympus officer for attended handling of unattributable names, ambiguous records, unresolved external custody or staff permissions.</p>\n<p><strong>Recovery copies.</strong> Serving erasure does not physically rewrite a private database export or Cloudflare's observed up-to-30-day recovery history. Only the newest privately restored and verified export is kept; a superseded export is destroyed after its exact approved cleanup, and each export has a 365-day maximum age. Acceptance of its applicable release can dispose of it sooner. Until disposal or expiry, a copy can contain the data as captured. These are separate operator obligations, not an automatic all-copy erasure claim.</p>\n<p>Recovery is attended: keep the site closed before restoring and until subsequent erasures and the generation suppression records have been replayed. Reapply the News suppression and changes, and restore the current typed appointments and leadership-directory settings so a removed or corrected name stays corrected. Check the settings-audit name rewrite before reopening. Never treat an older database as current membership, role, proof or privacy authority. The owner verifies each recovery copy's age and records replacement and cleanup receipts; unresolved custody remains explicitly open.</p>\n\n<h2>Your copy</h2>\n<p>The separate identify-only connection also provides a curated, bounded own-account download after departure, denial, or without a website account. It includes the registered own-record sections but caps larger sections at one thousand records and states omissions; it does not offer the ordinary session’s history continuations. Authentication credentials, structural references to other accounts, proof digests, raw provider pointers and staff details are withheld. User-authored labels and free text can name other people. A consumed download form is not proof that your browser saved the file; reconnect for a fresh form after a lost download response.</p>\n<p>With an existing site session, open <a href=\"https://olympus.roachcouncil.com/privacy/account\">Account data controls</a> to download the current\ncurated JSON copy through <code>/api/me/export</code>. It contains selected account, application, vote, friend and\nreserved-name records; selected bot status, character, pending-request and queue fields without verification codes;\nand the registered community sections. Names you chose as labels and your own free text are copied as supplied and\ncan name other people. Legacy Battle.net freshness flags in this copy are not evidence of Forever ownership.\nDated actions are a paginated list of time and action name, beginning with the earliest thousand. Account data controls\nprovide a script-free history view with a Next page button and a separate download for the displayed page. A traversal\ncaptures a range of retained actions: later entries, including backdated entries and the traversal's own copy records,\nare excluded. Its continuation is signed for the same site session and sent in a form body, never an address. If retained\nrecords change the captured count or page position, continuation is refused; start again for a fresh range. This is not\nan immutable multi-page database snapshot. Other account-copy sections are read afresh with each download, at that\ncopy's generatedAt. The copy also contains a separately paged event-change range where your account was the recorded actor: event ID,\nchange kind, time, and the names of changed fields. It does not include arbitrary event-history text, field values,\nother people's changes to your events, or rows already removed by retention. The event-change controls have their own\nsigned continuation and Current/Next view; action continuations cannot select this collection. A download using an\nevent-change continuation freshly captures its action page and other sections, while retaining that event-change\nrange. Contribution-decision history is a third, separately paged retained range. It includes a decision once when\nits subject is your account or its recorded actor is explicitly your member/staff account. A subject-owned decision\nmay have an unrecognized legacy actor; actor-only legacy aliases are not treated as an established account link.\nOnly the recognized decision action, time and your relation (subject, actor or both) are copied. Counterpart identities,\npayment evidence, obligation identifiers, raw actor text and expired decisions are omitted. Its dedicated account form\nand signed continuation use the same original site session. Current/Next and private rate-window resume work without\nscripts or continuation URLs. A download continuing one range captures its other history collections afresh.\nAll three collections and downloads share the same approximate five-read hourly limit. A captured count and page\nposition detect certain retained-range changes; they do not authenticate equal-count content changes or provide an\nimmutable snapshot. Keep any saved continuation private and use the same original site session before it expires.\nThe copy excludes staff notes and\nreasons, staff identities, raw roster snapshots and private payment details. Typed appointment/directory names and\nprivacy inbox conversations are not matched into this account copy; use the request conversation for those.\nThis is not a complete export of every bot, operational, backup, Discord, game-client or officer-computer record.\nIf information you expect is missing, ask Olympus volunteer administration. History views and download pages share a limit of about\nfive per hour, enforced approximately in memory; longer histories may need a later window.</p>\n\n<h2>Contact</h2>\n<p>Contact Olympus volunteer administration through Olympus’s officers in Asmongold’s Discord server for attended help. Own-account downloads and erasure requests use <a href=\"https://olympus.roachcouncil.com/privacy/access\">Privacy account connection</a>; existing case credentials use <a href=\"https://olympus.roachcouncil.com/privacy/case\">Read an existing case</a>.</p>\n\n<p class=\"meta related\">See also the <a href=\"/terms\">Terms of Service</a>.</p>\n<!-- olympus:slot ACCOUNT_CONTROLS start -->\n<section class=\"data-controls\"><h2>Privacy and account data</h2><p><a href=\"https://olympus.roachcouncil.com/privacy/account\">Account data controls</a> · <a href=\"https://olympus.roachcouncil.com/privacy/access\">Connect Discord for privacy actions</a> · <a href=\"https://olympus.roachcouncil.com/privacy/case\">Read an existing case</a></p></section>\n<!-- olympus:slot ACCOUNT_CONTROLS end -->\n<!-- olympus:slot BNET_LOGIN start -->\n\n<!-- olympus:slot BNET_LOGIN end -->\n</main>\n</body>\n</html>\n";
const TERMS = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Olympus Verify — Terms of Service</title>\n<meta name=\"color-scheme\" content=\"dark\">\n<link rel=\"stylesheet\" href=\"/static/policies.css\">\n</head>\n<body class=\"olympus-policy\">\n<a class=\"skip-link\" href=\"#policy-content\">Skip to policy</a>\n<header class=\"policy-header\">\n<a class=\"brand\" href=\"/\"><img src=\"/static/olympus-icon.png\" alt=\"\" width=\"40\" height=\"40\">Olympus</a>\n<nav aria-label=\"Policies\"><a href=\"/privacy\">Privacy Policy</a><a href=\"/terms\" aria-current=\"page\">Terms of Service</a></nav>\n</header>\n<main id=\"policy-content\" tabindex=\"-1\">\n<h1>Terms of Service</h1>\n<p class=\"meta\">Olympus Verify and the Olympus guild site · last updated 5 October 2026</p>\n\n<p>Olympus Verify and the Olympus guild site are provided free, as-is, with no warranty, by the volunteer staff of one\nWorld of Warcraft guild, for the use of that guild's members and applicants. They are not a commercial service, and the\nbot is not available for installation elsewhere.</p>\n\n<h2>Age and eligibility</h2>\n<p>You must be at least 13 and meet any higher minimum age required by Discord or the law where you live. You must\nalso be eligible to use World of Warcraft under the Blizzard terms that apply to your region. Obtain any agreement\nfrom a parent or legal guardian required by those terms. Discord sign-in does not verify your age for Olympus.</p>\n\n<h2>Using it</h2>\n<p>By verifying a character you confirm it is yours. Claiming someone else's character,\nsharing verification codes, or using the bot to gain access you were not given is grounds for losing guild and Discord\naccess.</p>\n\n<h2>The guild site</h2>\n<p>By applying you confirm that what you wrote is true and that the account is yours. Joke, troll and abusive\napplications are permanently denied, and so is voting under several accounts. A leadership application goes on the\nvoting board, where members can read it and vote on it, only when you tick the box that allows it; you can withdraw it\nat any time. Applying (first choice or backup), voting, writing someone in and entering a reserved name are requests\nand opinions, not promises: the guild's leadership decides roles and invitations.</p>\n<p><strong>The community pages.</strong> What you list in the directory or offer as crafting is yours to change or\nwithdraw at any time while the page is on; a calendar answer can be given or changed until the event starts; a character\nname you enter is a claim until it matches the officers' record.\nThe records the officers keep about you there &mdash; trials, restriction cases and their watch-lists, departure items,\nthe dues ledger &mdash; are the guild's staff records; they do not by themselves grant or remove access, roles or\nmembership. Guild dues are the guild's own arrangement: the ledger records what the officers confirm was paid, the mail\nreference is a matching aid and not proof of payment, and any question about a payment or a week is for the officers.\nThe site's administrators have a rank-planning page whose drafts stay in their own browser; a draft is a proposal, never a\nchange in the guild. The leadership directory of the Olympus guilds is a record the administrators keep; being listed\nthere gives no powers. News notices are the administrators' announcements to the guild, and the News figures are\napproximate counts; neither is a promise.</p>\n<p><strong>A full guild.</strong> While Olympus I is full, a character whose code was confirmed keeps its place in the\ninvite queue, and a refusal for lack of space costs it no invite attempt. A place in the queue is not a seat and promises\nno date, and names reserved on the site go first. The bot removes nobody to make room; officers may remove inactive\ncharacters.</p>\n<p><strong>Renamed characters.</strong> A character renamed because Blizzard required it, as a site administrator\ndecides, has to be verified again and its owner has to apply again; unless another of the owner's characters is in the\nguild, the Guild Member role is held until the leadership accepts the new application and the character is verified\nagain.</p>\n<p>The site is a free, non-commercial fan project. It is not affiliated with or endorsed by Blizzard Entertainment. It\nuses interface artwork and icons from the World of Warcraft game client, which remain the property of Blizzard\nEntertainment, Inc., and two interface fonts taken from the same client (Friz Quadrata, whose embedded notice names\nInternational Typeface Corporation, 1997, and Morpheus, whose embedded notice names Kiwi Media/Design, Eric Oehler, 1996),\nreproduced with those notices intact; nothing here claims their ownership or grants any right to redistribute them, and\nthe site's own code licence does not extend to them. World of Warcraft and Blizzard Entertainment are trademarks or\nregistered trademarks of Blizzard Entertainment, Inc.</p>\n\n<h2>How it tells you about your access</h2>\n<p>The bot never sends direct messages. When something changes about your own access &mdash; your character is on the\nguild roster, you are back in the invite queue, or a seat was freed &mdash; it posts a short notice in the server's bot\nnotices channel (#olympus-notices) and mentions you, so you get an ordinary notification. Only the welcome (your character is on the guild roster) is said in\nfull; every other notice, including being back in the queue or a freed seat, and anything you might not want read out in\nfront of the server, such as an invite that was declined or refused or an application that was decided, only says there\nis an update, and <code>/verify-status</code> shows you the detail privately. In that\nchannel it posts nothing else &mdash; no announcements, no marketing &mdash; and it is rate-limited; whether a notice\nreaches you depends on the channel's permissions and on Discord. The bot also writes to the staff's own channels: its log\nlines, review cards and, where the officers switch it on, a daily digest of how many things wait for them, as counts only.\nYou can mute the notices channel at any time; <code>/verify-status</code> always shows the same information on request.</p>\n\n<h2>Availability</h2>\n<p>Staff may change, pause or retire the bot at any time. Guild membership itself is decided by officers, not by this\nsoftware; the bot only reflects the in-game guild roster.</p>\n\n<p class=\"meta related\">See also the <a href=\"/privacy\">Privacy Policy</a>.</p>\n<!-- olympus:slot ACCOUNT_CONTROLS start -->\n<section class=\"data-controls\"><h2>Privacy and account data</h2><p><a href=\"https://olympus.roachcouncil.com/privacy/account\">Account data controls</a> · <a href=\"https://olympus.roachcouncil.com/privacy/access\">Connect Discord for privacy actions</a> · <a href=\"https://olympus.roachcouncil.com/privacy/case\">Read an existing case</a></p></section>\n<!-- olympus:slot ACCOUNT_CONTROLS end -->\n<!-- olympus:slot BNET_LOGIN start -->\n\n<!-- olympus:slot BNET_LOGIN end -->\n</main>\n</body>\n</html>\n";
export const POLICY_SOURCE_DIGEST = "8675dc9034403d7955916082744542f086ab2d8fb2b94f8dd07136d8bfd7e74c";
/** A marker alone cannot activate collection; policy-release.ts stays immutable OFF. */
export const PRIVACY_DESCRIBES_BNET_LOGIN = false;
export function policyDocument(path: string): string | null {
  if (["/policies", "/policies/index.html"].includes(path)) return INDEX;
  if (["/privacy", "/privacy-policy", "/privacy.html"].includes(path)) return PRIVACY;
  if (["/terms", "/tos", "/terms-of-service", "/terms.html"].includes(path)) return TERMS;
  return null;
}
